import {loadRoute,esc} from '/data.js';
let articles=[],projects=[],columns=[],chapters=[],galleryArt=[],categories=['全部'],homeAbout='',aboutData=null,pageInfo={total:0,page:1,pageSize:12};
let routeController=null;
function applyState(state){articles=state.articles;projects=state.projects;columns=state.columns;chapters=state.chapters;galleryArt=state.gallery;homeAbout=state.homeAbout;aboutData=state.about;pageInfo=state.page;categories=['全部',...columns.map(c=>c.name)];}
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],main=$('#main');let cleanup=()=>{},currentKey='',motionPaused=false,columnReturnY=0;const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const covers={'understand-the-code':'network-fibers.png','connect-the-notes':'sculptural-glass.png','notice-the-everyday':'life-notes.png','small-motion':'cinema-poster.jpg','io-multiplexing':'network-fibers.png','notes-as-map':'sculptural-glass.png','css-variables':'sculptural-glass.png','first-notes':'life-notes.png'};
const cover=a=>a.cover?.src||'/assets/'+(covers[a.id]||'sculptural-glass.png');


const meta=a=>`<span class="category-label">${a.category}</span>${a.isDemo?'<span class="sample-label">示例</span>':''}`;
const rule=(n,en,link,text)=>`<div class="section-rule" data-reveal><span>${n} / ${en}</span>${link?`<a href="${link}">${text}</a>`:''}</div>`;
const filters=c=>`<div class="filters" role="group" aria-label="文章分类">${categories.map(x=>`<button class="filter" data-category="${x}" aria-pressed="${x===c}">${x}</button>`).join('')}</div>`;
function imageCard(a,i=0){return `<a class="story-card article-row" href="#/article/${a.id}" data-reveal style="--delay:${i*70}ms"><div class="story-media"><img src="${cover(a)}" alt="${a.category}文章封面，示意图" width="1536" height="1024" loading="lazy"><span class="image-corner" aria-hidden="true">＋</span><span class="image-number">${String(i+1).padStart(2,'0')}</span></div><div class="story-meta">${meta(a)}</div><h3>${a.title}</h3><p>${a.desc}</p><span class="read-meta">${a.date} · ${a.read}</span></a>`}
function artGallery(){if(!galleryArt.length)return '';return `<section class="art-gallery" aria-labelledby="art-gallery-title"><div class="art-gallery-frame"><header class="art-gallery-heading"><div><p>VISUAL INSPIRATIONS / ${galleryArt.length} IMAGES</p><h2 id="art-gallery-title">A different perspective.</h2></div><div class="art-gallery-actions"><button class="art-view-all" type="button">VIEW ALL ${galleryArt.length} <span aria-hidden="true">＋</span></button><button class="art-motion-toggle" type="button" aria-label="Pause artwork motion" aria-pressed="false">PAUSE</button></div></header><div class="art-rows">${Array.from({length:Math.min(2,galleryArt.length)},(_,row)=>row).map(row=>`<div class="art-rail" data-row="${row}" aria-label="艺术灵感，第${row+1}排"><div class="art-track"><div class="art-sequence" data-original>${galleryArt.slice(row*Math.ceil(galleryArt.length/2),(row+1)*Math.ceil(galleryArt.length/2)).map((a,j)=>`<a class="art-card" href="${a.src}" data-art="${row*Math.ceil(galleryArt.length/2)+j}" aria-label="查看 ${a.title}"><img src="${a.src}" alt="${a.alt}" width="1240" height="800" loading="lazy" decoding="async"><span class="art-card-caption"><span>${String(row*Math.ceil(galleryArt.length/2)+j+1).padStart(2,'0')}</span><strong>${a.title}</strong><span aria-hidden="true">＋</span></span></a>`).join('')}</div></div></div>`).join('')}</div><footer class="art-gallery-caption"><span>画廊精选 · 来源信息见图片详情</span><span class="art-scroll-hint">AUTOPLAY · ${galleryArt.length} IMAGES</span></footer></div><dialog class="art-lightbox" aria-labelledby="art-lightbox-title"><div class="art-lightbox-top"><span class="art-lightbox-count"></span><button type="button" class="art-lightbox-close" aria-label="关闭图片">CLOSE ×</button></div><figure><img alt=""><figcaption><h3 id="art-lightbox-title"></h3><p class="art-lightbox-credit"></p></figcaption></figure><div class="art-lightbox-controls"><button type="button" data-art-step="-1" aria-label="上一张图片">PREVIOUS</button><span>画廊图片</span><button type="button" data-art-step="1" aria-label="下一张图片">NEXT</button></div></dialog></section>`}
function aboutStage(){return `<section class="about-stage" aria-labelledby="about-stage-title" lang="en"><div class="about-objects" aria-hidden="true">${['moon','brick','smile','cursor'].map(name=>`<div class="about-object about-object-${name}"><img src="/assets/about/glass-${name}.png" alt="" width="1254" height="1254" loading="lazy" decoding="async"></div>`).join('')}</div><div class="about-stage-content"><h2 id="about-stage-title">ABOUT ME</h2><p class="about-statement">${homeAbout}</p><a class="about-stage-link" href="#/about">MORE ABOUT ME</a></div></section>`}
function articleNumeral(n){if(n>4)return `<span>${String(n).padStart(2,'0')}</span>`;const zero='<path fill-rule="evenodd" d="M49 1C16-2 1 15 0 48C-1 81 13 99 46 100C79 102 95 84 96 51C97 19 83 2 49 1ZM47 31C38 31 37 39 37 51C37 64 39 71 47 71C55 71 58 64 58 50C58 37 55 31 47 31Z"/>';const figures={1:'<path d="M104 10L160 1V99H120V37L104 40Z"/>',2:'<path d="M105 12Q123-1 145 1Q181 0 187 24Q192 42 175 57L153 74H189V99H104V76L145 43Q156 34 145 29Q130 27 105 42Z"/>',4:'<path fill-rule="evenodd" d="M151 2H188V59H195V83H188V100H153V83H102V55L130 2H164L137 58H153V26Z"/>',3:'<path d="M105 9Q128-1 150 1Q181 1 187 22Q193 41 174 48Q195 54 191 75Q187 100 151 101Q124 102 104 91V64Q128 77 145 75Q159 74 151 64L133 63L137 41Q155 42 151 32Q139 25 105 39Z"/>'};return `<svg viewBox="0 0 192 102" aria-hidden="true" focusable="false" fill="currentColor">${zero}${figures[n]}</svg>`}
const columnArticles=c=>c.articleIds.map(id=>articles.find(a=>a.id===id)).filter(Boolean);
function columnMosaic(c){return `<div class="column-mosaic">${c.images.map((index,i)=>{const a=index;return `<img class="column-image column-image-${i}" src="${a.src}" alt="${i===2?c.name+'专栏的艺术示意：'+a.alt:''}" width="1240" height="800" loading="lazy" decoding="async">`}).join('')}</div>`}
function columnsStage(){return `<section class="columns-stage" aria-labelledby="columns-title"><header class="columns-heading"><h2 id="columns-title">COLUMNS</h2><p>沿着不同的方向，慢慢展开。</p></header><div class="column-stack">${columns.map((c,i)=>`<span class="column-anchor" id="column-${c.id}" aria-hidden="true"></span><article class="column-panel" style="--column-i:${i}" aria-labelledby="column-title-${c.id}" data-column="${c.id}"><header class="column-panel-head"><span class="column-number" aria-hidden="true">${articleNumeral(i+1)}</span><div class="column-copy"><h3 id="column-title-${c.id}">${c.name}</h3><p>${c.intro}</p><span>${c.count} 篇文章</span></div><a class="column-enter" href="#/column/${c.id}">进入专栏 <span aria-hidden="true">↗</span></a></header>${columnMosaic(c)}<footer class="column-panel-caption"><span>专栏内容与图片</span><span>${String(i+1).padStart(2,'0')} / ${String(columns.length).padStart(2,'0')}</span></footer></article>`).join('')}</div></section>`}
function columnDirectory(id){const c=columns.find(c=>c.id===id);if(!c)return notfound();const list=columnArticles(c),credit=c.images;return `<section class="column-directory"><header class="column-directory-head"><a class="column-back" href="#/" data-columns-back>← 返回首页专栏</a><p class="column-kicker">COLUMN ${String(c.order).padStart(2,'0')} / 专栏</p><h1>${c.name}</h1><p class="column-directory-intro">${c.intro}</p><span class="column-directory-count">${list.length} 篇文章</span></header><div class="column-directory-art">${columnMosaic(c)}</div><section class="column-directory-list" aria-label="${c.name}文章目录"><h2>专栏目录</h2>${list.map((a,i)=>`<a class="column-directory-row" href="#/article/${a.id}"><span class="column-article-no">${String(i+1).padStart(2,'0')}</span><div><h3>${a.title}</h3><p>${a.desc}</p><small>${a.read}${a.isDemo?' · 示例文章':''}</small></div><span aria-hidden="true">↗</span></a>`).join('')}</section><details class="column-credits"><summary>封面图片来源与许可</summary><p>图片的作者、来源与许可由媒体库记录。</p>${credit.map(a=>`<p>${a.caption||a.alt}${a.credit?' · '+a.credit:''}${a.source?` · <a href="${a.source}" target="_blank" rel="noopener">来源</a>`:''}${a.licenseUrl?` · <a href="${a.licenseUrl}" target="_blank" rel="noopener">${a.licenseName||'许可'}</a>`:a.licenseName?' · '+a.licenseName:''}</p>`).join('')}</details><nav class="column-directory-nav" aria-label="其他专栏">${columns.filter(x=>x.id!==id).map(x=>`<a href="#/column/${x.id}">${x.name} ↗</a>`).join('')}</nav></section>`}
function articleIndex(){return `<section class="article-index" aria-labelledby="article-index-title"><div class="article-sky" aria-hidden="true"><img class="article-stars" src="/assets/article-sky/stars.webp" alt="" width="2400" height="1350" loading="lazy"><div class="article-nebula"><img src="/assets/article-sky/milky-way.webp" alt="" width="2400" height="1350" loading="lazy"></div></div><h2 id="article-index-title">ARTICLE</h2><div class="article-index-list">${articles.slice(0,3).map((a,i)=>`<a class="article-index-row" href="#/article/${a.id}" data-reveal><span class="article-index-number" aria-hidden="true">${articleNumeral(i+1)}</span><div class="article-index-copy"><h3>${a.title}</h3><p>${a.desc}</p><span class="article-index-meta">${a.category} · ${a.read}${a.isDemo?' · 示例文章':''}</span></div></a>`).join('')}</div><div class="article-index-footer"><a href="#/articles">浏览全部文章</a></div></section>`}
function home(){return `<div class="magazine-home"><section class="collectible-hero" aria-labelledby="collectible-title" data-current="green" data-playback="loading"><nav class="collectible-nav" aria-label="Main navigation"><a href="#/about">ABOUT ME<span aria-hidden="true">→</span></a><div><a href="#/articles">NOTES</a><a href="#/projects">PROJECTS</a><a href="#/life">LIFE</a></div></nav><h1 id="collectible-title"><span>ALWAYS</span><span>CURIOUS.</span></h1><div class="collectible-crop"><div class="collectible-stage" tabindex="0" role="group" aria-label="Three felt portraits. Use left and right arrow keys to switch."><div class="collectible-parallax"><figure class="collectible-figure" data-look="green" data-slot="center"><img src="/assets/trio/felt-green-peace.png" alt="Green felt outfit, arms raised in two peace signs" width="1024" height="1536" fetchpriority="high" draggable="false"></figure><figure class="collectible-figure" data-look="pink" data-slot="right"><img src="/assets/trio/felt-pink-hoodie.png" alt="Pink felt hoodie, both arms raised" width="1024" height="1536" fetchpriority="high" draggable="false"></figure><figure class="collectible-figure" data-look="blue" data-slot="left"><img src="/assets/trio/felt-blue-pointing.png" alt="Blue felt streetwear, one hand pointing forward" width="1024" height="1536" fetchpriority="high" draggable="false"></figure></div></div></div><div class="collectible-bottom"><a class="collectible-intro" href="#/articles">A LITTLE CODE.<br>A LOT OF CURIOSITY.<span>READ MY NOTES →</span></a><div class="collectible-controls" aria-label="Portrait carousel controls"><div class="look-progress" aria-label="Choose a portrait"><button data-select="0" aria-label="Show green outfit" aria-pressed="true"><span></span></button><button data-select="1" aria-label="Show pink outfit" aria-pressed="false"><span></span></button><button data-select="2" aria-label="Show blue outfit" aria-pressed="false"><span></span></button></div><div class="look-actions"><span class="look-count" aria-hidden="true">01 / 03</span><button data-step="-1" aria-label="Previous portrait">←</button><button data-step="1" aria-label="Next portrait">→</button><button class="look-toggle" aria-pressed="false" aria-label="Pause automatic rotation"><span aria-hidden="true">||</span><span class="toggle-label">PAUSE</span></button></div><span class="look-status" aria-live="off">THREE SIDES. ONE ME.</span></div></div><p class="collectible-error" role="status" hidden>Portraits are unavailable. You can still explore the notes below.</p></section>
${artGallery()}
${aboutStage()}
${articleIndex()}
${columnsStage()}</div>`}
function articleList(category='全部'){const list=articles;return `<section class="archive-head section-wrap"><p class="eyebrow">01 / THE READING ROOM</p><h1>阅读室<span>。</span></h1><div><p>技术、学习与日常观察。<br>每一篇，都是一个问题的切面。</p><span class="archive-count">${String(pageInfo.total).padStart(2,'0')}<small>篇文章</small></span></div></section><section class="archive-content section-wrap">${filters(category)}<div class="archive-grid">${list.map(imageCard).join('')||'<p class="empty">这个分类还没有文章。</p>'}</div>${pagination('articles',category)}</section>`}
function sidebar(id){return `<aside class="chapter-sidebar" id="chapters" aria-label="知识库章节"><a class="sidebar-home" href="#/knowledge">知识库 / INDEX</a>${chapters.map(([n,t,items])=>`<details open><summary>${n} · ${t}</summary>${items.map(([aid,title])=>`<a href="#/knowledge/${aid}" ${aid===id?'aria-current="page"':''}>${title}</a>`).join('')}</details>`).join('')}</aside>`}
function reading(id,knowledge=false){const a=articles.find(x=>x.id===id);if(!a)return notfound();const sampleStory=['understand-the-code','connect-the-notes','notice-the-everyday'].includes(a.id);const toc=a.sections.map(([id,t])=>`<a href="#${id}" data-anchor="${id}">${t}</a>`).join('');const next=a.next;return `<header class="reading-cover ${sampleStory?'sample-reading-cover':''} ${a.id==='first-notes'?'light-cover':''}"><img src="${cover(a)}" alt="文章封面，示意图" width="1536" height="1024"><div class="reading-cover-content"><div class="breadcrumb"><a href="#/">首页</a><span>/</span><a href="${knowledge?'#/knowledge':'#/articles'}">${knowledge?'知识库':'文章'}</a><span>/</span><span>${a.category}</span></div><p class="eyebrow">${knowledge?'KNOWLEDGE / CHAPTER':'JOURNAL / ARTICLE'}${a.isDemo?' · 示例':''}</p><h1>${a.title}</h1><div class="read-meta">${a.date} · ${a.read}</div></div><span class="cover-index" aria-hidden="true">${String(articles.indexOf(a)+1).padStart(2,'0')}</span></header><div class="reading-shell ${sampleStory?'sample-reading':''} ${knowledge?'with-chapters':''}"><div class="reading-mobile">${knowledge?'<button class="chapter-toggle" aria-expanded="false" aria-controls="chapters">章节目录</button>':''}<details class="mobile-toc"><summary>本文目录</summary><div>${toc}</div></details></div>${knowledge?sidebar(id):''}<article class="reading-main"><div class="article-header"><p class="article-intro">${a.intro}</p><div class="meta">${meta(a)}</div></div><div class="prose">${a.body}</div><nav class="reading-footer" aria-label="文章翻页"><a href="#/${knowledge?'knowledge':'articles'}">返回${knowledge?'知识库':'文章列表'}</a>${next&&!knowledge?`<a href="#/article/${next.id}">下一篇<br><strong>${next.title}</strong></a>`:''}</nav></article><aside class="toc" aria-label="本文目录"><h2>IN THIS ARTICLE</h2>${toc}</aside></div>`}
function projectList(){return `<section class="project-intro section-wrap"><p class="eyebrow">03 / SELECTED EXPERIMENTS</p><h1>小小的尝试。<br><em>真实的过程。</em></h1><p>这里展示原型与内容设计示例。<br>从想法，到结构，再到可以体验的细节。</p></section><div class="exhibit-list">${projects.map((p,i)=>`<a class="full-exhibit ${i?'dark-exhibit':''}" href="#/project/${p.id}"><div class="full-exhibit-art" data-reveal><img src="${p.cover?.src||'/assets/sculptural-glass.png'}" alt="${p.title}的展览示意图" width="1536" height="1024"><span>${String(i+1).padStart(2,'0')}</span></div><div class="full-exhibit-copy" data-reveal><p class="eyebrow">${p.type}${p.isDemo?' / 示例项目':''}</p><h2>${p.title}</h2><p>${p.desc}</p><div>${p.tags.map(t=>`<span>${t}</span>`).join('')}</div><strong>进入展览 <i aria-hidden="true">＋</i></strong></div></a>`).join('')}</div>`}
function projectDetail(id){const p=projects.find(x=>x.id===id);if(!p)return notfound();return `<article class="project-case"><header class="case-cover"><img src="${p.cover?.src||'/assets/sculptural-glass.png'}" alt="${p.title}封面" width="1536" height="1024"><div><div class="breadcrumb"><a href="#/projects">项目展览</a><span>/</span><span>${p.isDemo?'示例项目':'项目'}</span></div><p class="eyebrow">${p.type}</p><h1>${p.title}</h1><p>${p.desc}</p></div><span class="case-big-no" aria-hidden="true">01</span></header><section class="case-section section-wrap"><span class="chapter-kicker">01 / THE IDEA</span><div><h2>项目记录</h2><p>${p.body.replaceAll('\n','<br>')}</p>${p.note?`<aside class="callout">${p.note}</aside>`:''}</div></section><section class="case-detail-band"><div class="section-wrap case-section"><span class="chapter-kicker">02 / THE STRUCTURE</span><div><h2>过程与细节</h2><div class="case-points">${p.details.map((d,i)=>`<div data-reveal><span>${String(i+1).padStart(2,'0')}</span><h3>${d}</h3></div>`).join('')}</div></div></div></section><section class="case-section section-wrap"><a class="solid-action" href="#/projects">返回项目展览</a></section></article>`}
function life(){return `<section class="life-archive section-wrap"><p class="eyebrow">04 / LIFE BETWEEN THE LINES</p><h1>日常，<em>也有回声。</em></h1><div class="life-archive-grid">${articles.map((a,i)=>`<figure data-reveal><img src="${cover(a)}" alt="${a.title}封面" width="1122" height="1402"><figcaption>${a.date}</figcaption></figure><article class="life-entry ${i%2?'offset-entry':''}" data-reveal><span class="eyebrow">${a.category}${a.isDemo?' / 示例随记':''}</span><h2>${a.title}</h2><p>${a.desc}</p><a class="text-action" href="#/article/${a.id}">阅读全文 <span aria-hidden="true">＋</span></a></article>`).join('')||'<p class="empty">还没有发布随记。</p>'}</div>${pagination('life','')}</section>`}
function about(){const a=aboutData||{title:'关于',text:'',topics:[],note:''};return `<section class="about-intro section-wrap"><p class="eyebrow">05 / ABOUT THIS LITTLE CORNER</p><h1>记录，是另一种<br><em>认识世界的方式。</em></h1></section><section class="about-spread section-wrap"><div class="about-portrait"><span class="about-big-type" aria-hidden="true">HELLO.</span><img src="/assets/avatar-original.png" alt="蓝色外套毛毡分身" width="1024" height="1536"></div><div class="about-copy"><p class="eyebrow">我的小站</p><h2>${a.title}</h2><p>${a.text.replaceAll('\n','<br>')}</p><div class="about-topics">${a.topics.map(x=>`<span>${x}</span>`).join('')}</div>${a.note?`<aside class="callout">${a.note}</aside>`:''}</div></section>`}
function pagination(route,category){const total=Math.ceil(pageInfo.total/pageInfo.pageSize);if(total<=1)return '';const base='#/'+route+(category&&category!=='全部'?'/'+encodeURIComponent(category):'');return `<nav class="page-navigation" aria-label="分页">${pageInfo.page>1?`<a href="${base}?page=${pageInfo.page-1}">上一页</a>`:'<span></span>'}<span>第 ${pageInfo.page} / ${total} 页</span>${pageInfo.page<total?`<a href="${base}?page=${pageInfo.page+1}">下一页</a>`:'<span></span>'}</nav>`}
function notfound(){return `<section class="notfound section-wrap"><p class="eyebrow">A SMALL DETOUR</p><h1>这一页，<br>还在路上。</h1><a class="solid-action" href="#/articles">回到阅读室</a></section>`}
function setupExperience(){const root=$('.collectible-hero');if(!root)return()=>{};let cancelled=false,dispose=()=>{};import('/collectible.js').then(({mountCollectible})=>{if(cancelled)return;return mountCollectible(root)}).then(fn=>{if(typeof fn==='function'){if(cancelled)fn();else dispose=fn}}).catch(()=>{root.dataset.playback='static';root.querySelector('.look-status').textContent='STATIC PORTRAITS';root.querySelectorAll('button').forEach(b=>b.disabled=true)});return()=>{cancelled=true;dispose()}}
function setupGallery(){const root=$('.art-gallery');if(!root)return()=>{};let cancelled=false,dispose=()=>{};import('/gallery.js').then(({mountGallery})=>{if(cancelled)return;return mountGallery(root,galleryArt.map(x=>x.raw||x))}).then(fn=>{if(typeof fn==='function'){if(cancelled)fn();else dispose=fn}});return()=>{cancelled=true;dispose()}}
function setupAboutStage(){const root=$('.about-stage');if(!root)return()=>{};let cancelled=false,dispose=()=>{};import('/about-stage.js').then(({mountAboutStage})=>{if(cancelled)return;return mountAboutStage(root)}).then(fn=>{if(typeof fn==='function'){if(cancelled)fn();else dispose=fn}});return()=>{cancelled=true;dispose()}}
function setupArticleSky(){const root=$('.article-index');if(!root)return()=>{};let cancelled=false,dispose=()=>{};import('/article-sky.js').then(({mountArticleSky})=>{if(cancelled)return;dispose=mountArticleSky(root)}).catch(()=>{root.dataset.revealMode='static'});return()=>{cancelled=true;dispose()}}
function setupColumns(){const root=$('.columns-stage');if(!root)return()=>{};let cancelled=false,dispose=()=>{};import('/columns.js').then(({mountColumns})=>{if(cancelled)return;dispose=mountColumns(root)});return()=>{cancelled=true;dispose()}}
function setupReveal(){const items=$$('[data-reveal]');if(!items.length)return()=>{};if(reduced.matches||motionPaused){items.forEach(e=>e.classList.add('revealed'));return()=>{}}document.documentElement.classList.add('motion-ready');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('revealed');observer.unobserve(e.target)}}),{threshold:.08,rootMargin:'0px 0px -20px 0px'});items.forEach(e=>observer.observe(e));return()=>observer.disconnect()}
function closeMenu(){$('#main-nav').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');$('.menu-toggle').setAttribute('aria-label','打开导航')}
async function render(force=false){const parsed=new URL(location.hash.slice(1)||'/',location.origin);let [route='',id='']=parsed.pathname.slice(1).split('/');try{id=decodeURIComponent(id)}catch{id=''}const key=route+'/'+id+parsed.search;if(!force&&key===currentKey&&main.children.length)return;const previousKey=currentKey;currentKey=key;routeController?.abort();routeController=new AbortController();const controller=routeController;cleanup();main.innerHTML='<section class="section-wrap content-status" aria-live="polite"><h1>正在打开这一页…</h1></section>';let html;try{if(!['','articles','column','article','knowledge','projects','project','life','about'].includes(route))throw Object.assign(new Error('NOT_FOUND'),{status:404});const state=await loadRoute(route,id,Number(parsed.searchParams.get('page')||1),controller.signal);if(controller.signal.aborted||currentKey!==key)return;applyState(state);switch(route){case'':html=home();break;case'articles':html=articleList(state.category||'全部');break;case'column':html=columnDirectory(id);break;case'article':html=reading(id);break;case'knowledge':html=state.emptyKnowledge?'<section class="section-wrap"><h1>知识库</h1><p>还没有发布章节内容。</p></section>':reading(state.selectedId,true);break;case'projects':html=projectList();break;case'project':html=projectDetail(id);break;case'life':html=life();break;case'about':html=about();break;}}catch(error){if(controller.signal.aborted)return;html=error.status===404?notfound():'<section class="section-wrap content-status" aria-live="polite"><h1>内容暂时无法加载。</h1><p>请稍后重试。</p><button class="solid-action" data-retry>重新加载</button></section>';}
document.body.className=route?(route==='column'?'interior-page column-page':'interior-page'):'collectible-home';main.innerHTML=html;document.title=route?(main.querySelector('h1')?.textContent||'我的小站')+' · 我的小站':'Always Curious — Notes & Experiments';closeMenu();$$('[data-nav]').forEach(a=>{const active=a.dataset.nav===(route==='article'?'articles':route==='project'?'projects':route||'home');if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});window.scrollTo({top:!route&&previousKey.startsWith('column/')?(columnReturnY||$('.columns-stage')?.offsetTop||0):0,behavior:'instant'});main.focus({preventScroll:true});document.documentElement.dataset.motion=motionPaused||reduced.matches?'off':'on';const sceneCleanup=setupExperience(),galleryCleanup=setupGallery(),aboutCleanup=setupAboutStage(),skyCleanup=setupArticleSky(),columnsCleanup=setupColumns(),revealCleanup=setupReveal();let tocObserver;if($('.prose')){tocObserver=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting)$$('.toc a').forEach(a=>a.classList.toggle('active',a.dataset.anchor===e.target.id))},{rootMargin:'-10% 0px -60% 0px'});$$('.prose h2').forEach(h=>tocObserver.observe(h));$('.toc a')?.classList.add('active')}cleanup=()=>{sceneCleanup();galleryCleanup();aboutCleanup();skyCleanup();columnsCleanup();revealCleanup();tocObserver?.disconnect()}}
$('.menu-toggle').addEventListener('click',()=>{const open=$('.menu-toggle').getAttribute('aria-expanded')!=='true';$('#main-nav').classList.toggle('open',open);$('.menu-toggle').setAttribute('aria-expanded',String(open));$('.menu-toggle').setAttribute('aria-label',open?'关闭导航':'打开导航')});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();$$('.mobile-toc[open]').forEach(d=>d.open=false)}});document.addEventListener('click',e=>{if(e.target.closest('a[href="#main"]')){e.preventDefault();main.focus();main.scrollIntoView();return}if(e.target.closest('[data-retry]')){render(true);return}if(e.target.closest('.columns-stage .column-enter'))columnReturnY=window.scrollY;const filter=e.target.closest('[data-category]');if(filter){location.hash='/articles/'+(filter.dataset.category==='全部'?'':encodeURIComponent(filter.dataset.category));return}const anchor=e.target.closest('[data-anchor]');if(anchor){e.preventDefault();document.getElementById(anchor.dataset.anchor)?.scrollIntoView({behavior:reduced.matches?'auto':'smooth'});$$('.mobile-toc[open]').forEach(d=>d.open=false);return}const chapter=e.target.closest('.chapter-toggle');if(chapter){const open=chapter.getAttribute('aria-expanded')!=='true';chapter.setAttribute('aria-expanded',String(open));$('#chapters').classList.toggle('open',open)}});window.addEventListener('hashchange',()=>render());render();
